#[must_use]
pub fn for_mode(mode: ModeLevel) -> &'static Icon {
    match mode {
        ModeLevel::Off => &CIRCLE_OFF,
        ModeLevel::Watch => &EYE,
        ModeLevel::Ask => &HAND,
        ModeLevel::Block => &BAN,
    }
}

#[must_use]
pub fn for_assurance(level: &str) -> &'static Icon {
    match level {
        "AL0" => &LIST,
        "AL1" => &BINOCULARS,
        "AL2" => &ROUTE,
        "AL3" => &BOX,
        "AL4" => &SHIELD_CHECK,
        _ => &SHIELD,
    }
}
